    add.u32 %r53, %r52, %r15;        // + out_y
    mul.lo.u32 %r54, %r53, %r7;       // * Wout
    add.u32 %r55, %r54, %r13;        // + out_x
    mul.wide.u32 %rd46, %r55, 2;      // *2 -> byte offset
    add.u64 %rd47, %rd12, %rd46;
    st.global.f16 [%rd47], %h2;

$END:
    ret;
